"""Build an offline field-review workspace from frozen predictions, without loading gold CSVs."""
import argparse
import hashlib
import json
import os
import shutil
from pathlib import Path


HTML = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>流水核对工作台</title><style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#20304b;background:#f3f5f8}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #d8deea;background:white;padding:9px 12px;border-radius:7px;color:#263650}button.primary{background:#204e78;color:white;border-color:#204e78}button:disabled{opacity:.45;cursor:not-allowed}header{background:#102d49;color:white;padding:22px 28px;display:flex;align-items:center;justify-content:space-between;gap:16px}header h1{font-size:22px;margin:0 0 7px}header p{margin:0;color:#bfcfdd;font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap}.bar{padding:16px 28px;background:white;border-bottom:1px solid #dbe1eb;display:flex;gap:12px;align-items:center}.bar input{min-width:230px}.bar select,.bar input,.editor input,.reviewer{padding:9px 11px;border:1px solid #d5deea;border-radius:6px;background:white}.stat{font-size:13px;color:#607188;margin-left:auto}.layout{display:grid;grid-template-columns:minmax(300px,34%) minmax(500px,66%);height:calc(100vh - 179px)}aside{overflow:auto;border-right:1px solid #dbe1eb;padding:14px}main{overflow:auto;padding:22px}.row{width:100%;display:block;text-align:left;margin:0 0 9px;padding:14px;border:1px solid #e1e6ed;border-radius:10px;background:white}.row.active{border:2px solid #204e78;padding:13px}.row-head{display:flex;justify-content:space-between;gap:9px;font-weight:650;font-size:14px}.muted{color:#748196;font-size:12px;margin-top:7px;word-break:break-all}.badge{font-size:11px;padding:3px 7px;border-radius:5px;background:#edf2f8;color:#4e6079}.warn{background:#fff2db;color:#925e0a}.good{background:#e2f3eb;color:#196243}.card{background:white;padding:18px;border:1px solid #dfe5ee;border-radius:11px;margin-bottom:16px}.card h2{font-size:17px;margin:0 0 12px}.issues{border-left:3px solid #d59935;background:#fff9ed;padding:12px 14px;margin:10px 0;font-size:13px;line-height:1.7}.issue{display:block;margin:9px 0}.issue input{margin-right:7px}.editor{display:grid;grid-template-columns:1fr 1fr;gap:11px 18px}.field label{font-size:12px;color:#51617b;display:block;margin-bottom:6px}.field input{width:100%;color:#263650}.field input.flagged{border-color:#d59935;background:#fffdf7}.original{font-size:11px;color:#7c8798;margin-top:4px;overflow-wrap:anywhere}.sources{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.page{width:100%;height:auto;display:block;border:1px solid #e4e8ee;background:white}.empty{padding:50px 20px;color:#6a7890;text-align:center}#toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);padding:12px 20px;background:#102d49;color:white;border-radius:7px;display:none;z-index:5}.notice{font-size:12px;line-height:1.7;color:#6a7890}.review-actions{margin-top:15px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}@media(max-width:950px){.layout{grid-template-columns:1fr;height:auto}aside{max-height:38vh}.editor{grid-template-columns:1fr}header,.bar{padding:16px;flex-wrap:wrap}.stat{margin-left:0}main{padding:14px}}
</style><header><div><h1>流水核对工作台</h1><p>逐笔核对具体字段 · 原文整页可查 · 原始识别结果保持不变</p></div><div class="actions"><button id="draft">导出当前12列CSV</button><button id="audit">导出核对记录</button><button class="primary" id="final">导出已确认CSV</button></div></header>
<div class="bar"><select id="document" aria-label="选择材料"></select><select id="filter" aria-label="筛选流水"><option value="pending">待确认</option><option value="all">全部流水</option><option value="reviewed">已人工确认</option></select><input id="search" placeholder="搜索账号、名称、日期或金额" aria-label="搜索"><span class="stat" id="stats"></span></div>
<div class="layout"><aside id="list"></aside><main id="detail"></main></div><div id="toast"></div>
<script id="payload" type="application/json">__PAYLOAD__</script><script>
'use strict';const data=JSON.parse(document.getElementById('payload').textContent);for(const d of data.documents){d.issues=d.issues.flatMap(issue=>issue.rows.length>1?issue.rows.map(row=>({...issue,id:issue.id+'::'+row,rows:[row]})):[issue])}const columns=['accountNumber','accountName','bankName','transactionTime','transactionDate','direction','amount','balance','transactionType','counterpartyName','counterpartyAccount','counterpartyBank'];const labels=['本方账号','本方名称','本方银行','交易时间','交易日期','收支方向','金额','余额','交易类型','对方名称','对方账号','对方银行'];
const $=id=>document.getElementById(id);const storageKey='lawflow-review-'+data.runId;let saved={edits:{},reviews:{},reviewer:''};try{saved=JSON.parse(localStorage.getItem(storageKey))||saved}catch(e){}let selected=null;let selectedPage=null;let doc;
function element(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}function key(row){return doc.id+':'+row.id}function issueKey(issue){return doc.id+':'+issue.id}function unresolved(issue){return issue.severity!=='ADVISORY'&&!['CONFIRMED','CORRECTED'].includes(saved.reviews[issueKey(issue)]?.status)}function issues(row){return doc.issues.filter(issue=>issue.rows.includes(row.id))}function values(row){return saved.edits[key(row)]||row.values}function persist(){try{localStorage.setItem(storageKey,JSON.stringify(saved))}catch(e){toast('当前浏览器无法保存，请导出核对记录。')}}function toast(text){$('toast').textContent=text;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}
for(const item of data.documents){const option=element('option',item.label);option.value=item.id;$('document').append(option)}function chooseDoc(){doc=data.documents.find(d=>d.id===$('document').value);selected=null;selectedPage=null;render()}function pendingRows(){return doc.rows.filter(row=>issues(row).some(unresolved))}function render(){const search=$('search').value.trim().toLowerCase(),filter=$('filter').value;const filtered=doc.rows.filter(row=>{const todo=issues(row).some(unresolved),reviewed=issues(row).some(issue=>saved.reviews[issueKey(issue)]);return(filter==='all'||filter==='pending'&&todo||filter==='reviewed'&&reviewed&&!todo)&&values(row).join(' ').toLowerCase().includes(search)});$('list').replaceChildren();const documentIssues=doc.issues.filter(issue=>!issue.rows.length&&unresolved(issue));if(!doc.complete||documentIssues.length){const warning=element('div',!doc.complete?'材料覆盖尚未确认完整，需要重新处理。':'存在整份材料的检查事项。','issues');for(const issue of documentIssues){const line=element('div',issue.message);for(const page of issue.pages||[]){const link=element('a',` 查看第 ${page} 页`);link.href=doc.images[String(page)];link.target='_blank';link.rel='noopener';line.append(link)}warning.append(line)}$('list').append(warning)}if(!filtered.length)$('list').append(element('div','当前筛选下没有流水。','empty'));for(const row of filtered){const v=values(row),button=element('button',undefined,'row'+(selected?.id===row.id?' active':''));const head=element('div',undefined,'row-head');head.append(element('span',v[9]||v[10]||'对方未提供'),element('span',(v[5]==='OUT'?'−':v[5]==='IN'?'+':'')+v[6]));button.append(head,element('div',v[4]+' · '+(v[8]||'类型待确认'),'muted'),element('div','本方 '+v[0],'muted'));const todo=issues(row).some(unresolved),reviewed=issues(row).some(issue=>saved.reviews[issueKey(issue)]);button.append(element('div',todo?'待确认':reviewed?'已人工确认':'自动处理完成','badge '+(todo?'warn':reviewed?'good':'')));button.onclick=()=>{selected=row;selectedPage=null;render()};$('list').append(button)}$('stats').textContent=`${doc.rows.length} 笔 · ${pendingRows().length} 笔待确认`;const ready=doc.complete&&!doc.issues.some(unresolved);$('final').disabled=!ready;if(!selected&&filtered.length)selected=filtered[0];renderDetail()}
function renderDetail(){const panel=$('detail');panel.replaceChildren();if(!selected){panel.append(element('div',doc.rows.length?'选择一笔流水查看。':'本份材料未生成交易。','empty'));return}const row=selected,v=values(row),rowIssues=issues(row),card=element('section',undefined,'card');card.append(element('h2',`流水 ${row.number} · ${v[4]||'日期待确认'}`));const edits=[];const checks=[];if(rowIssues.length){const box=element('div',undefined,'issues');box.append(element('strong','请核对以下具体事项'));for(const issue of rowIssues){const label=element('label',undefined,'issue'),check=document.createElement('input');check.type='checkbox';check.checked=!unresolved(issue);label.append(check,document.createTextNode((issue.field?labels[columns.indexOf(issue.field)]+'：':'')+issue.message));box.append(label);checks.push({issue,check})}card.append(box)}else card.append(element('p','本笔没有自动待办；仍可对照原文修改。','notice'));const grid=element('div',undefined,'editor');columns.forEach((name,i)=>{const field=element('div',undefined,'field'),label=element('label',labels[i]),input=document.createElement('input');input.value=v[i];input.setAttribute('aria-label',labels[i]);if(rowIssues.some(issue=>issue.field===name&&unresolved(issue)))input.className='flagged';field.append(label,input,element('div','原始：'+(row.values[i]||'（未提供）'),'original'));grid.append(field);edits.push(input)});card.append(grid);const actions=element('div',undefined,'review-actions'),reviewer=document.createElement('input');reviewer.className='reviewer';reviewer.placeholder='核对人';reviewer.value=saved.reviewer||'';reviewer.setAttribute('aria-label','核对人');const confirm=element('button','保存本笔核对','primary'),uncertain=element('button','保留为无法确认');confirm.onclick=()=>{if(!reviewer.value.trim())return toast('请填写核对人。');if(checks.some(item=>!item.check.checked))return toast('请逐项核对，或保留为无法确认。');const next=edits.map(input=>input.value);if(!next[0].trim())return toast('请确认本方账号。');if(!next[6]||Number(next[6])<0)return toast('请填写非负的交易金额。');const date=new Date(next[4]+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(next[4])||!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==next[4])return toast('日期尚不能确认，请保留为无法确认。');for(const i of [6,7])if(next[i]&&!/^-?\d+(?:\.\d{1,2})?$/.test(next[i]))return toast('金额和余额请使用数字，最多两位小数。');if(!['IN','OUT'].includes(next[5]))return toast('方向请使用IN或OUT。');const changed=next.some((value,i)=>value!==row.values[i]);saved.edits[key(row)]=next;saved.reviewer=reviewer.value.trim();for(const issue of rowIssues)saved.reviews[issueKey(issue)]={status:changed?'CORRECTED':'CONFIRMED',reviewer:saved.reviewer,reviewedAt:new Date().toISOString(),originalValues:row.values,values:next};persist();toast('核对记录已保存；原始结果未改写。');render()};uncertain.onclick=()=>{if(!reviewer.value.trim())return toast('请填写核对人。');saved.reviewer=reviewer.value.trim();for(const issue of rowIssues)saved.reviews[issueKey(issue)]={status:'UNRESOLVED',reviewer:saved.reviewer,reviewedAt:new Date().toISOString()};persist();render()};actions.append(reviewer,confirm,uncertain);card.append(actions,element('p','自动处理完成不等于人工核验，也不代表通过收费盲测。未解决事项会阻止导出“已确认”版本。','notice'));panel.append(card);const source=element('section',undefined,'card');source.append(element('h2','原文整页'));const pages=row.pages;if(!pages.length)source.append(element('p','未保存可定位页面；此材料不能作为最终核验结果。','notice'));const buttons=element('div',undefined,'sources');if(!selectedPage&&pages.length)selectedPage=pages[0];for(const page of pages){const button=element('button',`第 ${page} 页`,page===selectedPage?'primary':'');button.onclick=()=>{selectedPage=page;renderDetail()};buttons.append(button)}source.append(buttons);if(selectedPage){const img=document.createElement('img');img.className='page';img.src=doc.images[String(selectedPage)];img.alt=`原材料第${selectedPage}页，完整页面`;source.append(img);const link=element('a','单独打开完整图片');link.href=img.src;link.target='_blank';link.rel='noopener';source.append(link)}panel.append(source)}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)}function csv(final){if(final&&(!doc.complete||doc.issues.some(unresolved)))return toast('还有未完成事项，不能导出已确认版本。');const quote=s=>/[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;const content='\uFEFF'+[columns,...doc.rows.map(values)].map(row=>row.map(quote).join(',')).join('\r\n')+'\r\n';download(doc.id+(final?'_已确认':'_待确认')+'.csv',content,'text/csv;charset=utf-8')}$('draft').onclick=()=>csv(false);$('final').onclick=()=>csv(true);$('audit').onclick=()=>download('流水核对记录.json',JSON.stringify({runId:data.runId,exportedAt:new Date().toISOString(),...saved},null,2),'application/json');$('document').onchange=chooseDoc;$('filter').onchange=()=>{selected=null;render()};$('search').oninput=()=>{selected=null;render()};chooseDoc();
</script></html>'''


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--suite', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    documents = []
    fingerprint = hashlib.sha256()
    (args.output / 'csv').mkdir(exist_ok=True)
    for bank in sorted(p for p in args.suite.iterdir() if p.is_dir() and p.name.isdigit()):
        delivery = bank / 'delivery'
        if not (delivery / 'result.json').exists():
            raise ValueError(f'{bank.name}: frozen delivery missing')
        prediction_bytes = (delivery / 'result.json').read_bytes()
        fingerprint.update(bank.name.encode()); fingerprint.update(prediction_bytes)
        result = json.loads(prediction_bytes)
        shutil.copy2(delivery / 'candidate.csv', args.output / 'csv' / (bank.name + '_待确认.csv'))
        registry = json.loads((delivery / 'registry.json').read_text())
        manifest = json.loads((bank / 'document-manifest.json').read_text())
        rows = []
        for index, row in enumerate(result['rows']):
            pages = sorted({registry['rows'][ref.split(':')[1]]['page'] for ref in row['sourceObservationIds'] if ref.startswith('source:')})
            rows.append({'id': row['id'], 'number': index + 1, 'values': row['values'], 'pages': pages})
        labels = dict(zip(['accountNumber', 'accountName', 'bankName', 'transactionTime', 'transactionDate', 'direction',
            'amount', 'balance', 'transactionType', 'counterpartyName', 'counterpartyAccount', 'counterpartyBank'],
            ['本方账号', '本方名称', '本方银行', '交易时间', '交易日期', '收支方向', '金额', '余额', '交易类型', '对方名称', '对方账号', '对方银行']))
        def readable(text):
            for field, label in labels.items(): text = text.replace(field, label)
            return text
        issues = [{'id': item['id'], 'field': item['field'], 'message': readable(item['message']), 'severity': item['severity'],
                   'rows': [rows[n - 1]['id'] for n in item['outputRows']],
                   'pages': sorted(set(item.get('sourcePages', []) +
                       [registry['rows'][str(n)]['page'] for n in item['sourceRows'] if str(n) in registry['rows']] +
                       [registry['cells'][str(n)]['page'] for n in item['sourceCells'] if str(n) in registry['cells']]))}
                  for item in result['pending']]
        images = {str(page): os.path.relpath(bank / 'images' / f'upright-{page:02}.jpg', args.output)
                  for page in registry['pages']}
        documents.append({'id': bank.name, 'label': manifest.get('displayName') or bank.name + ' · ' + (manifest.get('issuerBankName') or '银行材料'),
                          'complete': result['complete'], 'rows': rows, 'issues': issues, 'images': images})
    payload = json.dumps({'runId': args.suite.name + '-' + fingerprint.hexdigest()[:16], 'documents': documents, 'standardAnswersRead': False}, ensure_ascii=False).replace('<', '\\u003c')
    (args.output / 'index.html').write_text(HTML.replace('__PAYLOAD__', payload))
    print(json.dumps({'documents': len(documents), 'transactions': sum(len(d['rows']) for d in documents),
                      'path': str(args.output / 'index.html')}, ensure_ascii=False))


if __name__ == '__main__':
    main()
